import type { CSSProperties } from "react";

const APP_URL = process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";

// ─── スタイル定数 ───────────────────────────────────────────────────────────────

const s = {
  // レイアウト
  container: {
    maxWidth: "1080px",
    margin: "0 auto",
    padding: "0 24px",
  } satisfies CSSProperties,

  // ナビ
  nav: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "20px 0",
  } satisfies CSSProperties,

  navLogo: {
    fontWeight: 700,
    fontSize: "1.2rem",
    color: "var(--color-primary)",
  } satisfies CSSProperties,

  navCta: {
    display: "inline-flex",
    alignItems: "center",
    gap: "8px",
    background: "var(--color-primary)",
    color: "#fff",
    padding: "10px 20px",
    borderRadius: "8px",
    fontWeight: 600,
    fontSize: "0.9rem",
    transition: "background 0.2s",
  } satisfies CSSProperties,

  // ヒーロー
  hero: {
    padding: "96px 0 80px",
    textAlign: "center",
  } satisfies CSSProperties,

  heroEyebrow: {
    display: "inline-block",
    background: "#eef2ff",
    color: "var(--color-primary)",
    borderRadius: "99px",
    padding: "4px 16px",
    fontSize: "0.85rem",
    fontWeight: 600,
    marginBottom: "24px",
  } satisfies CSSProperties,

  heroTitle: {
    fontSize: "clamp(2rem, 5vw, 3.2rem)",
    fontWeight: 800,
    lineHeight: 1.25,
    letterSpacing: "-0.02em",
    marginBottom: "24px",
  } satisfies CSSProperties,

  heroPrimary: {
    color: "var(--color-primary)",
  } satisfies CSSProperties,

  heroDesc: {
    fontSize: "1.15rem",
    color: "var(--color-muted)",
    maxWidth: "600px",
    margin: "0 auto 40px",
  } satisfies CSSProperties,

  heroActions: {
    display: "flex",
    gap: "16px",
    justifyContent: "center",
    flexWrap: "wrap" as const,
  } satisfies CSSProperties,

  btnPrimary: {
    display: "inline-block",
    background: "var(--color-primary)",
    color: "#fff",
    padding: "16px 36px",
    borderRadius: "10px",
    fontWeight: 700,
    fontSize: "1.05rem",
    boxShadow: "0 4px 14px rgba(79,70,229,0.35)",
  } satisfies CSSProperties,

  btnSecondary: {
    display: "inline-block",
    border: "2px solid var(--color-border)",
    color: "var(--color-text)",
    padding: "14px 32px",
    borderRadius: "10px",
    fontWeight: 600,
    fontSize: "1.05rem",
  } satisfies CSSProperties,

  // 課題セクション
  painSection: {
    background: "var(--color-surface)",
    padding: "80px 0",
  } satisfies CSSProperties,

  sectionLabel: {
    textAlign: "center",
    fontWeight: 700,
    fontSize: "0.85rem",
    letterSpacing: "0.08em",
    color: "var(--color-muted)",
    textTransform: "uppercase" as const,
    marginBottom: "16px",
  } satisfies CSSProperties,

  sectionTitle: {
    textAlign: "center",
    fontSize: "clamp(1.5rem, 3vw, 2.2rem)",
    fontWeight: 800,
    marginBottom: "48px",
    letterSpacing: "-0.01em",
  } satisfies CSSProperties,

  painGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))",
    gap: "20px",
  } satisfies CSSProperties,

  painCard: {
    background: "#fff",
    borderRadius: "var(--radius)",
    padding: "28px 24px",
    border: "1px solid var(--color-border)",
    display: "flex",
    gap: "16px",
    alignItems: "flex-start",
  } satisfies CSSProperties,

  painEmoji: {
    fontSize: "1.8rem",
    flexShrink: 0,
  } satisfies CSSProperties,

  painText: {
    fontSize: "0.95rem",
    color: "var(--color-text)",
    lineHeight: 1.6,
  } satisfies CSSProperties,

  // 機能セクション
  featureSection: {
    padding: "96px 0",
  } satisfies CSSProperties,

  featureGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))",
    gap: "28px",
  } satisfies CSSProperties,

  featureCard: {
    background: "var(--color-surface)",
    borderRadius: "var(--radius)",
    padding: "32px 28px",
    border: "1px solid var(--color-border)",
  } satisfies CSSProperties,

  featureIcon: {
    width: "48px",
    height: "48px",
    background: "#eef2ff",
    borderRadius: "12px",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: "1.5rem",
    marginBottom: "20px",
  } satisfies CSSProperties,

  featureTitle: {
    fontWeight: 700,
    fontSize: "1.1rem",
    marginBottom: "10px",
  } satisfies CSSProperties,

  featureDesc: {
    color: "var(--color-muted)",
    fontSize: "0.93rem",
    lineHeight: 1.65,
  } satisfies CSSProperties,

  // 対象ユーザー
  targetSection: {
    background: "var(--color-surface)",
    padding: "80px 0",
  } satisfies CSSProperties,

  targetGrid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
    gap: "16px",
    maxWidth: "800px",
    margin: "0 auto",
  } satisfies CSSProperties,

  targetCard: {
    background: "#fff",
    borderRadius: "var(--radius)",
    padding: "24px 16px",
    border: "1px solid var(--color-border)",
    textAlign: "center",
  } satisfies CSSProperties,

  targetEmoji: {
    fontSize: "2.2rem",
    marginBottom: "12px",
  } satisfies CSSProperties,

  targetLabel: {
    fontWeight: 600,
    fontSize: "0.95rem",
  } satisfies CSSProperties,

  // CTA
  ctaSection: {
    padding: "96px 0",
    textAlign: "center",
  } satisfies CSSProperties,

  ctaBox: {
    background: "linear-gradient(135deg, var(--color-primary) 0%, #7c3aed 100%)",
    borderRadius: "20px",
    padding: "64px 40px",
    color: "#fff",
  } satisfies CSSProperties,

  ctaTitle: {
    fontSize: "clamp(1.6rem, 3vw, 2.4rem)",
    fontWeight: 800,
    marginBottom: "16px",
    letterSpacing: "-0.01em",
  } satisfies CSSProperties,

  ctaDesc: {
    fontSize: "1.05rem",
    opacity: 0.85,
    marginBottom: "36px",
  } satisfies CSSProperties,

  ctaBtn: {
    display: "inline-block",
    background: "#fff",
    color: "var(--color-primary)",
    padding: "16px 40px",
    borderRadius: "10px",
    fontWeight: 700,
    fontSize: "1.05rem",
    boxShadow: "0 4px 14px rgba(0,0,0,0.2)",
  } satisfies CSSProperties,

  // フッター
  footer: {
    borderTop: "1px solid var(--color-border)",
    padding: "32px 0",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    flexWrap: "wrap" as const,
    gap: "12px",
  } satisfies CSSProperties,

  footerLogo: {
    fontWeight: 700,
    color: "var(--color-primary)",
  } satisfies CSSProperties,

  footerMuted: {
    color: "var(--color-muted)",
    fontSize: "0.85rem",
  } satisfies CSSProperties,
};

// ─── データ ────────────────────────────────────────────────────────────────────

const PAINS = [
  { emoji: "📞", text: "欠席連絡の電話・LINEが業務を中断させる" },
  { emoji: "📋", text: "振替日程の調整をExcel・紙台帳で手作業管理" },
  { emoji: "😓", text: "振替可能枠の把握が煩雑でダブルブッキングが起きる" },
  { emoji: "📧", text: "振替期限のリマインドを手動で送るのが手間" },
  { emoji: "📊", text: "月次の出欠・振替状況の集計に時間がかかる" },
  { emoji: "🔒", text: "生徒情報の管理が属人化していてリスクがある" },
];

const FEATURES = [
  {
    icon: "📅",
    title: "振替予約をセルフで完結",
    desc: "生徒がスマホから空き枠を確認して自分で振替予約。スタッフへの問い合わせが大幅に減ります。",
  },
  {
    icon: "🔔",
    title: "欠席連絡・振替クレジット自動管理",
    desc: "欠席すると振替クレジットが自動付与。有効期限管理・消費履歴もすべて自動で記録されます。",
  },
  {
    icon: "👥",
    title: "複数スタジオ・クラス対応",
    desc: "複数店舗・複数クラスタイプを一元管理。スタッフ別のシフト管理も標準機能で対応。",
  },
  {
    icon: "📊",
    title: "管理画面・CSV エクスポート",
    desc: "管理者はブラウザから予約・出欠・振替クレジットをリアルタイムに確認。CSVで月次集計も即座に。",
  },
  {
    icon: "🔐",
    title: "法人・店舗ごとのアクセス制御",
    desc: "管理者・スタッフ・会員の三段階権限。店舗をまたいだデータアクセスを厳格に分離します。",
  },
  {
    icon: "🚀",
    title: "すぐ使える・すぐ拡張できる",
    desc: "法人登録から5分で利用開始。店舗・クラス・スタッフを自由に追加。初期費用ゼロで始められます。",
  },
];

const TARGETS = [
  { emoji: "🎹", label: "音楽教室" },
  { emoji: "🧘", label: "ヨガ・ピラティス" },
  { emoji: "💃", label: "ダンススタジオ" },
  { emoji: "🥋", label: "武道・格闘技" },
  { emoji: "🎨", label: "絵画・アート教室" },
  { emoji: "🏊", label: "スイミング" },
];

// ─── ページ ────────────────────────────────────────────────────────────────────

export default function LandingPage() {
  return (
    <>
      {/* ナビゲーション */}
      <header style={{ borderBottom: "1px solid var(--color-border)" }}>
        <div style={s.container}>
          <nav style={s.nav}>
            <span style={s.navLogo}>振替管理</span>
            <a href={`${APP_URL}/corporation/register`} style={s.navCta}>
              無料で始める →
            </a>
          </nav>
        </div>
      </header>

      <main>
        {/* ヒーロー */}
        <section style={s.hero}>
          <div style={s.container}>
            <span style={s.heroEyebrow}>スタジオ・教室向けクラウドサービス</span>
            <h1 style={s.heroTitle}>
              振替の手間を、
              <br />
              <span style={s.heroPrimary}>まるごとなくす。</span>
            </h1>
            <p style={s.heroDesc}>
              欠席連絡から振替予約・クレジット管理まで。
              <br />
              生徒もスタッフも、もう電話もLINEも必要ありません。
            </p>
            <div style={s.heroActions}>
              <a href={`${APP_URL}/corporation/register`} style={s.btnPrimary}>
                無料で始める
              </a>
              <a href={`${APP_URL}/login`} style={s.btnSecondary}>
                ログイン
              </a>
            </div>
          </div>
        </section>

        {/* 課題 */}
        <section style={s.painSection}>
          <div style={s.container}>
            <p style={s.sectionLabel}>こんなお悩みありませんか？</p>
            <h2 style={s.sectionTitle}>振替管理のよくある課題</h2>
            <div style={s.painGrid}>
              {PAINS.map((p) => (
                <div key={p.text} style={s.painCard}>
                  <span style={s.painEmoji}>{p.emoji}</span>
                  <p style={s.painText}>{p.text}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* 機能 */}
        <section style={s.featureSection}>
          <div style={s.container}>
            <p style={s.sectionLabel}>Features</p>
            <h2 style={s.sectionTitle}>すべての課題を解決する機能</h2>
            <div style={s.featureGrid}>
              {FEATURES.map((f) => (
                <div key={f.title} style={s.featureCard}>
                  <div style={s.featureIcon}>{f.icon}</div>
                  <h3 style={s.featureTitle}>{f.title}</h3>
                  <p style={s.featureDesc}>{f.desc}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* 対象 */}
        <section style={s.targetSection}>
          <div style={s.container}>
            <p style={s.sectionLabel}>こんな教室に</p>
            <h2 style={s.sectionTitle}>業種を問わず対応</h2>
            <div style={s.targetGrid}>
              {TARGETS.map((t) => (
                <div key={t.label} style={s.targetCard}>
                  <div style={s.targetEmoji}>{t.emoji}</div>
                  <p style={s.targetLabel}>{t.label}</p>
                </div>
              ))}
            </div>
          </div>
        </section>

        {/* CTA */}
        <section style={s.ctaSection}>
          <div style={s.container}>
            <div style={s.ctaBox}>
              <h2 style={s.ctaTitle}>今すぐ無料で始めましょう</h2>
              <p style={s.ctaDesc}>
                初期費用ゼロ・クレジットカード不要。法人登録から5分でご利用いただけます。
              </p>
              <a href={`${APP_URL}/corporation/register`} style={s.ctaBtn}>
                無料でアカウントを作成 →
              </a>
            </div>
          </div>
        </section>
      </main>

      {/* フッター */}
      <footer>
        <div style={{ ...s.container, ...s.footer }}>
          <span style={s.footerLogo}>振替管理</span>
          <span style={s.footerMuted}>© {new Date().getFullYear()} 振替管理. All rights reserved.</span>
        </div>
      </footer>
    </>
  );
}
